const ga700_param_meta_t* ga700_find_param_by_addr(uint16_t addr)
{
    int low = 0;
    int high = GA700_PARAM_COUNT - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (g_ga700_params[mid].address == addr) {
            return &g_ga700_params[mid];
        } else if (g_ga700_params[mid].address < addr) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return NULL;
}

const ga700_param_meta_t* ga700_find_param_by_code(const char *code)
{
    if (code == NULL) return NULL;
    for (size_t i = 0; i < GA700_PARAM_COUNT; i++) {
        if (strcasecmp(g_ga700_params[i].code, code) == 0) {
            return &g_ga700_params[i];
        }
    }
    return NULL;
}

bool ga700_is_valid_param_addr(uint16_t addr)
{
    return (ga700_find_param_by_addr(addr) != NULL);
}
